from dataclasses import dataclass

import pytest


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add, and Mul nodes to an int."""
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)
    raise TypeError(f"not an expression: {e!r}")


def test_eval_num() -> None:
    assert eval_expr(Num(7)) == 7


def test_eval_add() -> None:
    assert eval_expr(Add(Num(1), Num(2))) == 3


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(3), Num(4))) == 12


def test_eval_nested() -> None:
    assert eval_expr(Mul(Add(Num(2), Num(3)), Num(4))) == 20


def test_eval_negative_values() -> None:
    assert eval_expr(Add(Num(-5), Mul(Num(-2), Num(3)))) == -11


def test_eval_deep_right_chain() -> None:
    e: Expr = Num(1)
    for _ in range(50):
        e = Add(Num(1), e)
    assert eval_expr(e) == 51


def test_eval_rejects_non_expr() -> None:
    with pytest.raises(TypeError):
        eval_expr(42)  # type: ignore[arg-type]
